import React, { Component, ErrorInfo, ReactNode } from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';
import { MemoryRouter } from 'react-router-dom';
import { ThemeProvider } from './hooks/useTheme';

console.log("🏫 Initializing Exameno ECG Application...");

interface ErrorBoundaryProps {
  children?: ReactNode;
}

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
  errorInfo: any;
}

// Fix: Explicitly extending Component to resolve TypeScript inheritance errors
class GlobalErrorBoundary extends Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    // Fix: state initialization within React.Component subclass
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
    };
  }

  static getDerivedStateFromError(error: any): Partial<ErrorBoundaryState> {
    return { hasError: true, error: error };
  }

  componentDidCatch(error: any, errorInfo: ErrorInfo) {
    console.error("CRITICAL: Component Tree Error Caught", error, errorInfo);
    // Fix: setState is a method of React.Component
    this.setState({ errorInfo });
  }

  handleReset = () => {
    try {
      localStorage.clear();
      window.location.reload();
    } catch (e) {
      window.location.href = window.location.origin;
    }
  };

  render() {
    // Fix: Accessing state property inherited from React.Component
    if (this.state.hasError) {
      return (
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          minHeight: '100vh',
          backgroundColor: '#1a000d',
          color: 'white',
          fontFamily: 'system-ui, sans-serif',
          padding: '2rem',
          textAlign: 'center'
        }}>
          <div style={{ background: '#33001a', padding: '2rem', borderRadius: '1rem', border: '1px solid #4d0026', maxWidth: '800px', width: '100%' }}>
            <h1 style={{ color: '#ff5c96', fontSize: '1.8rem', marginBottom: '1rem' }}>Application Encountered an Error</h1>
            <p style={{ color: '#ff99bb', marginBottom: '1.5rem' }}>This usually happens if saved data becomes incompatible. Resetting the app usually fixes it.</p>

            <div style={{ textAlign: 'left', marginBottom: '1.5rem' }}>
              <pre style={{
                backgroundColor: 'rgba(0,0,0,0.4)',
                padding: '1rem',
                borderRadius: '0.5rem',
                overflow: 'auto',
                fontSize: '0.75rem',
                fontFamily: 'monospace',
                border: '1px solid #4d0026',
                color: '#ffe3ec',
                maxHeight: '300px'
              }}>
                {/* Fix: state property usage */}
                {this.state.error?.toString()}
                {this.state.errorInfo?.componentStack}
              </pre>
            </div>

            <div style={{ display: 'flex', gap: '1rem', justifyContent: 'center' }}>
              <button 
                onClick={() => window.location.reload()}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#4d0026',
                  color: 'white',
                  border: '1px solid #ff5c96',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reload App
              </button>
              <button 
                onClick={this.handleReset}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#b30059',
                  color: 'white',
                  border: 'none',
                  borderRadius: '0.5rem',
                  cursor: 'pointer',
                  fontWeight: 'bold'
                }}
              >
                Reset Data & Clear Cache
              </button>
            </div>
          </div>
        </div>
      );
    }

    // Fix: Accessing props property inherited from React.Component
    return this.props.children || null;
  }
}

const container = document.getElementById('root');
if (container) {
  const root = createRoot(container);
  root.render(
    <GlobalErrorBoundary>
      <MemoryRouter>
        <ThemeProvider>
          <App />
        </ThemeProvider>
      </MemoryRouter>
    </GlobalErrorBoundary>
  );
} else {
    console.error("Root element not found");
}

